project_task.solution:
class Character:
    def __init__(self, name, hp, power):
        self.name = name
        self.hp = hp
        self.power = power

    def attack(self, other):
        other.hp -= self.power

    def is_alive(self):
        return self.hp > 0

piko = Character("Piko", 30, 8)
bat = Character("Bat", 12, 3)
piko.attack(bat)
print(bat.hp, bat.is_alive())
